-- Domain 21: Marketing: Social, Email & Promotions | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 401
CREATE FUNCTION public.email_claim_batch(p_limit integer DEFAULT 50) RETURNS SETOF public.email_outbox
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE email_outbox o SET status = 'sending', attempts = attempts + 1, updated_at = now()
   WHERE o.id IN (SELECT id FROM email_outbox WHERE status = 'queued' AND (scheduled_at IS NULL OR scheduled_at <= now())
                   ORDER BY created_at LIMIT p_limit FOR UPDATE SKIP LOCKED)
  RETURNING o.*;
$$;

-- @seq 402
CREATE FUNCTION public.email_enqueue(p_tenant_id uuid, p_idempotency_key text, p_from text, p_to text[], p_subject text, p_html text DEFAULT NULL::text, p_text text DEFAULT NULL::text, p_category text DEFAULT 'transactional'::text, p_related_type text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid, p_attachments jsonb DEFAULT '[]'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_crm_customer_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; v_supp text[];
BEGIN
  IF NOT (platform_is_tenant_member(p_tenant_id) OR auth.role() = 'service_role') THEN
    RAISE EXCEPTION 'Not allowed for tenant %', p_tenant_id;
  END IF;
  IF p_html IS NULL AND p_text IS NULL THEN RAISE EXCEPTION 'Email needs an HTML or text body'; END IF;
  SELECT array_agg(lower(s.contact)) INTO v_supp FROM marketing_suppressions s
   WHERE s.tenant_id = p_tenant_id AND coalesce(s.channel,'email') = 'email' AND lower(s.contact) = ANY (SELECT lower(x) FROM unnest(p_to) x);
  INSERT INTO email_outbox(tenant_id, idempotency_key, category, from_address, to_addresses, subject, html_body, text_body,
                           related_type, related_id, attachments, scheduled_at, crm_customer_id, created_by, status, error)
  VALUES (p_tenant_id, p_idempotency_key, p_category, p_from, p_to, p_subject, p_html, p_text, p_related_type, p_related_id,
          coalesce(p_attachments,'[]'::jsonb), p_scheduled_at, p_crm_customer_id, auth.uid(),
          CASE WHEN v_supp IS NOT NULL AND p_category = 'marketing' THEN 'suppressed' ELSE 'queued' END,
          CASE WHEN v_supp IS NOT NULL THEN 'suppressed recipients: ' || array_to_string(v_supp, ', ') END)
  ON CONFLICT (tenant_id, idempotency_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM email_outbox WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
  END IF;
  RETURN v_id;
END $$;

-- @seq 403
CREATE FUNCTION public.email_inbound_attach_document(p_inbound_id uuid, p_storage_path text, p_file_name text, p_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m email_inbound_messages%ROWTYPE; a email_inbound_addresses%ROWTYPE; v_doc uuid; v_dup uuid;
BEGIN
  SELECT * INTO m FROM email_inbound_messages WHERE id = p_inbound_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown inbound email %', p_inbound_id; END IF;
  SELECT * INTO a FROM email_inbound_addresses WHERE id = m.address_id;
  IF a.purpose NOT IN ('receipts','bills') THEN RAISE EXCEPTION 'Address % is not a receipts/bills inbox', a.address; END IF;
  SELECT id INTO v_dup FROM acct_document_inbox WHERE tenant_id = m.tenant_id AND sha256 = p_sha256 ORDER BY created_at LIMIT 1;
  INSERT INTO acct_document_inbox(tenant_id, entity_id, doc_kind, source, file_name, storage_path, sha256, status, duplicate_of_id)
  VALUES (m.tenant_id, acct_default_entity(m.tenant_id), CASE a.purpose WHEN 'bills' THEN 'bill' ELSE 'receipt' END, 'email',
          p_file_name, p_storage_path, p_sha256, CASE WHEN v_dup IS NULL THEN 'uploaded' ELSE 'duplicate' END, v_dup)
  RETURNING id INTO v_doc;
  UPDATE email_inbound_messages SET document_inbox_ids = document_inbox_ids || v_doc,
         attachments_status = CASE WHEN cardinality(document_inbox_ids) + 1 >= jsonb_array_length(attachments) THEN 'done' ELSE attachments_status END
   WHERE id = m.id;
  RETURN v_doc;
END $$;

-- @seq 404
CREATE FUNCTION public.email_mark_sent(p_outbox_id uuid, p_resend_email_id text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE email_outbox SET resend_email_id = coalesce(p_resend_email_id, resend_email_id),
         status = CASE WHEN p_error IS NULL THEN 'sent' WHEN attempts >= 5 THEN 'failed' ELSE 'queued' END,
         sent_at = CASE WHEN p_error IS NULL THEN now() END, error = p_error, updated_at = now()
   WHERE id = p_outbox_id;
$$;

-- @seq 529
CREATE FUNCTION public.resend_process_webhook(p_inbox_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE w integration_webhook_inbox%ROWTYPE; o email_outbox%ROWTYPE; d jsonb; v_type text; v_at timestamptz; v_rank int; v_cur int;
        v_addr email_inbound_addresses%ROWTYPE; v_to text; v_docs uuid[] := '{}'; v_doc uuid; att jsonb;
BEGIN
  SELECT * INTO w FROM integration_webhook_inbox WHERE id = p_inbox_id AND provider_code = 'resend' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Resend webhook %', p_inbox_id; END IF;
  IF w.status = 'processed' THEN RETURN 'already processed'; END IF;
  IF NOT w.signature_valid THEN
    UPDATE integration_webhook_inbox SET status = 'rejected', error = 'invalid signature', processed_at = now() WHERE id = w.id;
    RETURN 'rejected';
  END IF;
  v_type := w.payload->>'type'; d := w.payload->'data';
  v_at := coalesce((w.payload->>'created_at')::timestamptz, now());

  IF v_type = 'email.received' THEN
    FOREACH v_to IN ARRAY ARRAY(SELECT lower(jsonb_array_elements_text(coalesce(d->'to','[]'::jsonb)))) LOOP
      SELECT * INTO v_addr FROM email_inbound_addresses WHERE lower(address) = v_to AND is_active;
      EXIT WHEN FOUND;
    END LOOP;
    IF v_addr.id IS NULL THEN
      UPDATE integration_webhook_inbox SET status = 'ignored', error = 'no inbound address matches', processed_at = now() WHERE id = w.id;
      RETURN 'ignored';
    END IF;
    INSERT INTO email_inbound_messages(tenant_id, address_id, resend_email_id, message_id, from_address, to_addresses, subject, attachments, routed_to, document_inbox_ids, attachments_status)
    VALUES (v_addr.tenant_id, v_addr.id, d->>'email_id', d->>'message_id', d->>'from',
            ARRAY(SELECT jsonb_array_elements_text(coalesce(d->'to','[]'::jsonb))), d->>'subject', coalesce(d->'attachments','[]'::jsonb),
            CASE WHEN v_addr.purpose IN ('receipts','bills') THEN 'acct_document_inbox' ELSE v_addr.purpose END, '{}',
            CASE WHEN jsonb_array_length(coalesce(d->'attachments','[]'::jsonb)) = 0 THEN 'none' ELSE 'awaiting_download' END)
    ON CONFLICT (resend_email_id) DO NOTHING;
    INSERT INTO email_events(tenant_id, inbox_id, resend_email_id, event_type, occurred_at, recipient, detail)
    VALUES (v_addr.tenant_id, w.id, d->>'email_id', v_type, v_at, v_to, d);
    UPDATE integration_webhook_inbox SET tenant_id = v_addr.tenant_id, status = 'processed', processed_at = now() WHERE id = w.id;
    RETURN 'processed';
  END IF;

  IF v_type LIKE 'email.%' THEN
    SELECT * INTO o FROM email_outbox WHERE resend_email_id = d->>'email_id' FOR UPDATE;
    INSERT INTO email_events(tenant_id, outbox_id, inbox_id, resend_email_id, event_type, occurred_at, recipient, detail)
    VALUES (o.tenant_id, o.id, w.id, d->>'email_id', v_type, v_at,
            (SELECT string_agg(x, ',') FROM jsonb_array_elements_text(CASE jsonb_typeof(d->'to') WHEN 'array' THEN d->'to' ELSE jsonb_build_array(d->>'to') END) x),
            coalesce(d->'bounce', d->'click', d->'failed', '{}'::jsonb));
    IF o.id IS NOT NULL THEN
      -- never move a message backwards (opened after delivered, etc.)
      v_rank := CASE v_type WHEN 'email.sent' THEN 1 WHEN 'email.delivery_delayed' THEN 2 WHEN 'email.delivered' THEN 3
                            WHEN 'email.opened' THEN 4 WHEN 'email.clicked' THEN 5 WHEN 'email.bounced' THEN 9
                            WHEN 'email.complained' THEN 9 WHEN 'email.failed' THEN 9 ELSE 0 END;
      v_cur := CASE o.status WHEN 'sent' THEN 1 WHEN 'delivery_delayed' THEN 2 WHEN 'delivered' THEN 3 WHEN 'opened' THEN 4
                             WHEN 'clicked' THEN 5 WHEN 'bounced' THEN 9 WHEN 'complained' THEN 9 WHEN 'failed' THEN 9 ELSE 0 END;
      UPDATE email_outbox SET
        status = CASE WHEN v_rank >= v_cur AND v_rank > 0 THEN replace(v_type, 'email.', '') ELSE status END,
        delivered_at = CASE WHEN v_type = 'email.delivered' THEN v_at ELSE delivered_at END,
        opened_at = CASE WHEN v_type = 'email.opened' THEN coalesce(opened_at, v_at) ELSE opened_at END,
        clicked_at = CASE WHEN v_type = 'email.clicked' THEN coalesce(clicked_at, v_at) ELSE clicked_at END,
        error = CASE WHEN v_type IN ('email.failed','email.bounced') THEN coalesce(d#>>'{failed,reason}', d#>>'{bounce,message}') ELSE error END,
        last_event_at = greatest(coalesce(last_event_at, v_at), v_at), updated_at = now()
       WHERE id = o.id;
      -- complaints and permanent bounces suppress future sends to that address
      IF v_type = 'email.complained' OR (v_type = 'email.bounced' AND coalesce(d#>>'{bounce,type}','') ILIKE 'permanent%') THEN
        INSERT INTO marketing_suppressions(tenant_id, contact, channel, source, reason)
        SELECT o.tenant_id, lower(x), 'email', 'resend', replace(v_type,'email.','')
          FROM unnest(o.to_addresses) x
         WHERE NOT EXISTS (SELECT 1 FROM marketing_suppressions s WHERE s.tenant_id = o.tenant_id AND lower(s.contact) = lower(x) AND coalesce(s.channel,'email') = 'email');
      END IF;
      UPDATE integration_webhook_inbox SET tenant_id = o.tenant_id WHERE id = w.id;
    END IF;
  ELSIF v_type LIKE 'domain.%' THEN
    UPDATE email_sender_domains SET status = coalesce(d->>'status', status), records = coalesce(d->'records', records), region = coalesce(d->>'region', region), updated_at = now()
     WHERE resend_domain_id = d->>'id';
  END IF;
  UPDATE integration_webhook_inbox SET status = 'processed', processed_at = now(), attempts = attempts + 1 WHERE id = w.id;
  RETURN 'processed';
END $$;

-- @seq 544
CREATE FUNCTION public.social_claim_outbox_events(p_limit integer DEFAULT 25) RETURNS TABLE(id uuid, tenant_id uuid, seller_id uuid, aggregate_type text, aggregate_id uuid, event_type text, payload jsonb, attempts integer)
    LANGUAGE sql
    AS $$
  UPDATE public.social_outbox_events e
     SET status = 'processing', attempts = e.attempts + 1, claimed_at = now()
   WHERE e.id IN (
     SELECT so.id FROM public.social_outbox_events so
      WHERE so.status IN ('pending', 'processing')
        AND so.next_attempt_at <= now()
        AND (so.status = 'pending'
             OR so.claimed_at IS NULL
             OR so.claimed_at < now() - interval '15 minutes')
      ORDER BY so.next_attempt_at ASC, so.id ASC
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
   )
   RETURNING e.id, e.tenant_id, e.seller_id, e.aggregate_type,
             e.aggregate_id, e.event_type, e.payload, e.attempts;
$$;

